void initializePins()
{

	// Initializing the clocks for ports A, B, G, H, I
	RCC->AHB1ENR |= 0b111000011;
	(void)RCC->AHB1ENR;   // read back so the clocks are running before GPIO access

	// Each pin only clears its own MODER/OTYPER bits so the SWD debug
	// pins (PA13, PA14) and PB3 keep their settings.

	// Initialization for 7-segment display pins (D2-D8 = A-G)

	// Initializes D2 (PG6, segment A) as push-pull output
	GPIOG->MODER  &= ~(3UL << (2 * 6));
	GPIOG->MODER  |=  (1UL << (2 * 6));
	GPIOG->OTYPER &= ~(1UL << 6);

	// Initializes D3 (PB4, segment B) as push-pull output
	GPIOB->MODER  &= ~(3UL << (2 * 4));
	GPIOB->MODER  |=  (1UL << (2 * 4));
	GPIOB->OTYPER &= ~(1UL << 4);

	// Initializes D4 (PG7, segment C) as push-pull output
	GPIOG->MODER  &= ~(3UL << (2 * 7));
	GPIOG->MODER  |=  (1UL << (2 * 7));
	GPIOG->OTYPER &= ~(1UL << 7);

	// Initializes D5 (PA8, segment D) as push-pull output
	GPIOA->MODER  &= ~(3UL << (2 * 8));
	GPIOA->MODER  |=  (1UL << (2 * 8));
	GPIOA->OTYPER &= ~(1UL << 8);

	// Initializes D6 (PH6, segment E) as push-pull output
	GPIOH->MODER  &= ~(3UL << (2 * 6));
	GPIOH->MODER  |=  (1UL << (2 * 6));
	GPIOH->OTYPER &= ~(1UL << 6);

	// Initializes D7 (PI3, segment F) as push-pull output
	GPIOI->MODER  &= ~(3UL << (2 * 3));
	GPIOI->MODER  |=  (1UL << (2 * 3));
	GPIOI->OTYPER &= ~(1UL << 3);

	// Initializes D8 (PI2, segment G) as push-pull output
	GPIOI->MODER  &= ~(3UL << (2 * 2));
	GPIOI->MODER  |=  (1UL << (2 * 2));
	GPIOI->OTYPER &= ~(1UL << 2);

	// Initialization for digit selection (D10-D13)

	// Initializes D10 (PI0) as push-pull output
	GPIOI->MODER  &= ~(3UL << (2 * 0));
	GPIOI->MODER  |=  (1UL << (2 * 0));
	GPIOI->OTYPER &= ~(1UL << 0);

	// Initializes D11 (PB15) as push-pull output
	GPIOB->MODER  &= ~(3UL << (2 * 15));
	GPIOB->MODER  |=  (1UL << (2 * 15));
	GPIOB->OTYPER &= ~(1UL << 15);

	// Initializes D12 (PB14) as push-pull output
	GPIOB->MODER  &= ~(3UL << (2 * 14));
	GPIOB->MODER  |=  (1UL << (2 * 14));
	GPIOB->OTYPER &= ~(1UL << 14);

	// Initializes D13 (PI1) as push-pull output
	GPIOI->MODER  &= ~(3UL << (2 * 1));
	GPIOI->MODER  |=  (1UL << (2 * 1));
	GPIOI->OTYPER &= ~(1UL << 1);
}

void flashDisplay(char *theString) {

	// Flashes segment 1
	flashSegment(*theString);

	// turns on segment 1. Reset should happen during the flashSegment function
	GPIOI->ODR |= 1;

	// Flashes segment 2
	flashSegment(*(++theString));

	GPIOB->ODR |= (0b1 << 15);

	// Flashes segment 3
	flashSegment(*(++theString));

	GPIOB->ODR |= (0b1 << 14);

	// Flashes segment 4
	flashSegment(*(++theString));

	GPIOI->ODR |= (0b1 <<1);
}

void flashSegment(char theCharacter) // possibly add code to turn lights on and off
{
	int segmentCode = translateCharacter(theCharacter);

	// Assigns bit 0 in the 7-segment display sequence to Segment A (D2 on the board, PG6 on the processor)
	GPIOG->ODR = 0 | ((segmentCode & 0b1) << 6);

	// Assigns bit 1 in the 7-segment display sequence to Segment B (D3 on the board, PB4 on the processor)
	GPIOB->ODR = ((segmentCode >> 1) & 1) << 4;

	// Assigns bit 2 in the 7-segment display sequence to Segment C (D4 on the board, PG7 on the processor)
	GPIOG->ODR |= ((segmentCode >> 2) & 1) << 7;

	// Assigns bit 3 in the 7-segment display sequence to Segment D (D5 on the board, PA8 on the processor)
	GPIOA->ODR = ((segmentCode >> 3) & 1) << 8;

	// Assigns bit 4 in the 7-segment display sequence to Segment E (D6 on the board, PH6 in the processor)
	GPIOH->ODR = ((segmentCode >> 4) & 1) << 6;

	// Assigns bit 5 in the 7-segment display sequence to Segment F (D7 on the board, PI3 in the processor)
	GPIOI->ODR = ((segmentCode >> 5) & 1) << 3;

	// Assigns Bit 6 in the 7-segment display sequence to Segment G (D8 on the board, PI2 on the processor)
	GPIOI->ODR |= ((segmentCode >> 6) & 1) << 2;
}

/**
 * Takes a character and translates it into a set of bits that are used
 * for displaying on a sever-segment display.
 */
int translateCharacter(char theCharacter)
{
	int segmentCode;

	switch (theCharacter){
	case '0':
		segmentCode = 0b0000001;
		break;
	case '1':
		segmentCode = 0b1001111;
		break;
	case '2':
		segmentCode = 0b0010010;
		break;
	case '3':
		segmentCode = 0b0000110;
		break;
	case '4':
		segmentCode = 0b1001100;
		break;
	case '5':
		segmentCode = 0b0100100;
		break;
	case '6':
		segmentCode = 0b0100000;
		break;
	case '7':
		segmentCode = 0b0001101;
		break;
	case '8':
		segmentCode = 0b0000000;
		break;
	case '9':
		segmentCode = 0b0000100;
		break;
	case 'a':
		segmentCode = 0b0001000;
		break;
	case 'd':
		segmentCode = 0b1000010;
		break;
	case 'e':
		segmentCode = 0b0110000;
		break;
	case 'i':
		segmentCode = 0b1001000;
		break;
	case 'r':
		segmentCode = 0b1111010;
		break;
	case 's':
		segmentCode = 0b0100100;
		break;
	case 'u':
		segmentCode = 0b1000001;
		break;
	case 'v':
		segmentCode = 0b0011100;
		break;
	default:
		segmentCode = 255;
		break;
	}

	return segmentCode;
}


void simple_delay(uint32_t count) {
    while (count--) {
        __asm__("NOP");
    }
}
